def cubic_lower(n):
    if n%4==2:return Fraction(n*(6*n-27),4)
    return Fraction(n*(6*n-33),4)

def degree_upper(n,d):
    # Resistance <= distance and diameter <= max(2,n-2*d+1).
    U=Fraction(n*d*max(2,n-2*d+1))
    # An even-regular connected graph is bridgeless; R <= (n-1)/3.
    if d%2==0: U=min(U,Fraction(n*d*(n-1),3))
    # Common-neighbor parallel paths give the dense-degree bound.
    if 2*d-n+2>0: U=min(U,Fraction(2*n*d,2*d-n+2))
    return U

